_a('crops_title', 'Crops that suit this soil', 'इस मिट्टी के लिए उपयुक्त फसलें', 'ಈ ಮಣ್ಣಿಗೆ ಹೊಂದುವ ಬೆಳೆಗಳು', 'இந்த மண்ணுக்கு ஏற்ற பயிர்கள்', 'ఈ నేలకు తగిన పంటలు', 'या मातीला योग्य पिके')
