for _c, _v in {
    'N_SSP': ('Cheapest phosphorus source. It also gives sulphur.', 'फॉस्फोरस का सबसे सस्ता स्रोत। इससे गंधक भी मिलता है।', 'ರಂಜಕದ ಅಗ್ಗದ ಮೂಲ. ಇದು ಗಂಧಕವನ್ನೂ ಕೊಡುತ್ತದೆ.', 'பாஸ்பரசின் மலிவான மூலம். இது கந்தகத்தையும் தருகிறது.', 'భాస్వరానికి చౌకైన మూలం. ఇది గంధకాన్ని కూడా ఇస్తుంది.', 'फॉस्फरसचा सर्वात स्वस्त स्रोत. यातून गंधकही मिळते.'),
    'N_DAP': ('DAP also gives nitrogen, so less urea is needed.', 'डीएपी से नाइट्रोजन भी मिलता है, इसलिए यूरिया कम लगता है।', 'ಡಿಎಪಿಯಿಂದ ಸಾರಜನಕವೂ ಸಿಗುತ್ತದೆ, ಆದ್ದರಿಂದ ಯೂರಿಯಾ ಕಡಿಮೆ ಸಾಕು.', 'டிஏபி நைட்ரஜனையும் தருகிறது, அதனால் யூரியா குறைவாகவே போதும்.', 'డీఏపీ నత్రజనిని కూడా ఇస్తుంది, కాబట్టి యూరియా తక్కువ సరిపోతుంది.', 'डीएपीमधून नायट्रोजनही मिळते, म्हणून युरिया कमी लागतो.'),
    'N_UREA': ('Apply on moist soil. Do not apply just before heavy rain.', 'नम मिट्टी में डालें। तेज बारिश से ठीक पहले न डालें।', 'ತೇವ ಮಣ್ಣಿನಲ್ಲಿ ಹಾಕಿ. ಭಾರೀ ಮಳೆಗೆ ಮೊದಲು ಹಾಕಬೇಡಿ.', 'ஈர மண்ணில் இடுங்கள். கனமழைக்கு சற்று முன் இடாதீர்கள்.', 'తేమ నేలలో వేయండి. భారీ వర్షానికి ముందు వేయవద్దు.', 'ओलसर मातीत द्या. जोरदार पावसाआधी देऊ नका.'),
    'N_ADV_MACRO': ('Skip this fertiliser this season. The soil already has enough.', 'इस मौसम यह खाद न डालें। मिट्टी में पहले से पर्याप्त है।', 'ಈ ಹಂಗಾಮಿನಲ್ಲಿ ಈ ಗೊಬ್ಬರ ಬೇಡ. ಮಣ್ಣಿನಲ್ಲಿ ಈಗಾಗಲೇ ಸಾಕಷ್ಟಿದೆ.', 'இந்த பருவத்தில் இந்த உரம் வேண்டாம். மண்ணில் ஏற்கனவே போதுமான அளவு உள்ளது.', 'ఈ సీజన్‌లో ఈ ఎరువు వద్దు. నేలలో ఇప్పటికే సరిపడా ఉంది.', 'या हंगामात हे खत नको. मातीत आधीच पुरेसे आहे.'),
    'N_ADV_MICRO': ('Do not apply this nutrient. The soil already has enough.', 'यह पोषक तत्व न डालें। मिट्टी में पहले से पर्याप्त है।', 'ಈ ಪೋಷಕಾಂಶ ಹಾಕಬೇಡಿ. ಮಣ್ಣಿನಲ್ಲಿ ಈಗಾಗಲೇ ಸಾಕಷ್ಟಿದೆ.', 'இந்த ஊட்டச்சத்தைப் போடாதீர்கள். மண்ணில் ஏற்கனவே போதுமான அளவு உள்ளது.', 'ఈ పోషకాన్ని వేయవద్దు. నేలలో ఇప్పటికే సరిపడా ఉంది.', 'हे अन्नद्रव्य देऊ नका. मातीत आधीच पुरेसे आहे.'),
    'N_GENERAL': ('The table dose for other crops is used. Check with your agriculture officer.', 'अन्य फसलों की तालिका वाली मात्रा ली गई है। अपने कृषि अधिकारी से पूछ लें।', 'ಇತರ ಬೆಳೆಗಳ ಕೋಷ್ಟಕದ ಪ್ರಮಾಣ ಬಳಸಲಾಗಿದೆ. ನಿಮ್ಮ ಕೃಷಿ ಅಧಿಕಾರಿಯನ್ನು ವಿಚಾರಿಸಿ.', 'பிற பயிர்களுக்கான அட்டவணை அளவு பயன்படுத்தப்பட்டுள்ளது. உங்கள் வேளாண் அலுவலரிடம் கேளுங்கள்.', 'ఇతర పంటల పట్టిక మోతాదు వాడారు. మీ వ్యవసాయ అధికారిని అడగండి.', 'इतर पिकांच्या तक्त्यातील मात्रा घेतली आहे. तुमच्या कृषी अधिकाऱ्याला विचारा.'),
    'N_BORON': ('Use carefully. The safe range for boron is narrow.', 'सावधानी से डालें। बोरॉन की सुरक्षित सीमा कम है।', 'ಎಚ್ಚರಿಕೆಯಿಂದ ಹಾಕಿ. ಬೋರಾನ್‌ನ ಸುರಕ್ಷಿತ ಮಿತಿ ಕಡಿಮೆ.', 'கவனமாக இடுங்கள். போரானின் பாதுகாப்பான அளவு குறைவு.', 'జాగ్రత్తగా వేయండి. బోరాన్ సురక్షిత పరిధి తక్కువ.', 'काळजीपूर्वक द्या. बोरॉनची सुरक्षित मर्यादा कमी आहे.'),
    'N_RETEST': ('Test the soil again after one season.', 'एक मौसम बाद मिट्टी की फिर जांच करें।', 'ಒಂದು ಹಂಗಾಮಿನ ನಂತರ ಮಣ್ಣನ್ನು ಮತ್ತೆ ಪರೀಕ್ಷಿಸಿ.', 'ஒரு பருவத்திற்குப் பிறகு மண்ணை மீண்டும் பரிசோதியுங்கள்.', 'ఒక సీజన్ తర్వాత నేలను మళ్లీ పరీక్షించండి.', 'एका हंगामानंतर माती पुन्हा तपासा.'),
    'N_SODIC': ('Mostly helps salty (sodic) soils. Confirm with a soil salinity test.', 'मुख्य रूप से खारी (सोडिक) मिट्टी में काम आता है। मिट्टी की लवणता जांच से पुष्टि करें।', 'ಮುಖ್ಯವಾಗಿ ಉಪ್ಪು (ಸೋಡಿಕ್) ಮಣ್ಣಿಗೆ ಸಹಾಯಕ. ಮಣ್ಣಿನ ಲವಣ ಪರೀಕ್ಷೆಯಿಂದ ಖಚಿತಪಡಿಸಿ.', 'பெரும்பாலும் உப்பு (சோடிக்) மண்ணுக்கு உதவும். மண் உவர்ப்பு சோதனையால் உறுதிப்படுத்துங்கள்.', 'ప్రధానంగా ఉప్పు (సోడిక్) నేలలకు ఉపయోగం. నేల లవణ పరీక్షతో నిర్ధారించుకోండి.', 'प्रामुख्याने खारवट (सोडिक) जमिनीत उपयोगी. जमिनीच्या क्षारता तपासणीने खात्री करा.'),
    'N_FOLIAR': ('This is an extra. It does not replace the basal dose.', 'यह अतिरिक्त है। यह बेसल खुराक की जगह नहीं लेता।', 'ಇದು ಹೆಚ್ಚುವರಿ. ಇದು ಬುಡದ ಗೊಬ್ಬರಕ್ಕೆ ಪರ್ಯಾಯವಲ್ಲ.', 'இது கூடுதல். இது அடியுரத்துக்கு மாற்று அல்ல.', 'ఇది అదనం. ఇది ఆధార మోతాదుకు ప్రత్యామ్నాయం కాదు.', 'हे अतिरिक्त आहे. बेसल मात्रेची जागा घेत नाही.'),
}.items():
    _a(_c, *_v)

# glossary
GLOSSARY_TERMS = ['pH', 'Nitrogen', 'Phosphorus', 'Potassium', 'Organic carbon', 'Micronutrients', 'Basal dose',
                  'Top dressing', 'FYM', 'Hectare and acre', 'Soil Health Card', 'ppm']
_a('g_title', 'Glossary', 'शब्दावली', 'ಪದಕೋಶ', 'சொற்களஞ்சியம்', 'పదకోశం', 'शब्दकोश')
_a('g_pH', 'Soil pH: shows if soil is acidic (below 6), neutral (6 to 7.5) or alkaline (above 7.5). Most crops grow best near neutral.',
   'मिट्टी का पीएच: बताता है कि मिट्टी अम्लीय (6 से कम), सामान्य (6 से 7.5) या क्षारीय (7.5 से अधिक) है। ज्यादातर फसलें सामान्य पीएच में अच्छी उगती हैं।',
   'ಮಣ್ಣಿನ ಪಿಎಚ್: ಮಣ್ಣು ಆಮ್ಲೀಯ (6ಕ್ಕಿಂತ ಕಡಿಮೆ), ಸಾಮಾನ್ಯ (6 ರಿಂದ 7.5) ಅಥವಾ ಕ್ಷಾರೀಯ (7.5ಕ್ಕಿಂತ ಹೆಚ್ಚು) ಎಂದು ತೋರಿಸುತ್ತದೆ. ಹೆಚ್ಚಿನ ಬೆಳೆಗಳು ಸಾಮಾನ್ಯ ಪಿಎಚ್‌ನಲ್ಲಿ ಚೆನ್ನಾಗಿ ಬೆಳೆಯುತ್ತವೆ.',
   'மண் pH: மண் அமிலம் (6க்குக் கீழ்), நடுநிலை (6 முதல் 7.5) அல்லது காரம் (7.5க்கு மேல்) என்பதைக் காட்டுகிறது. பெரும்பாலான பயிர்கள் நடுநிலைக்கு அருகில் நன்கு வளரும்.',
   'నేల పీహెచ్: నేల ఆమ్లం (6 కంటే తక్కువ), తటస్థం (6 నుండి 7.5) లేదా క్షారం (7.5 కంటే ఎక్కువ) అని చూపుతుంది. చాలా పంటలు తటస్థం దగ్గర బాగా పెరుగుతాయి.',
   'मातीचा पीएच: माती आम्लधर्मी (6 पेक्षा कमी), सामान्य (6 ते 7.5) की क्षारयुक्त (7.5 पेक्षा जास्त) हे दाखवतो. बहुतेक पिके सामान्य पीएचमध्ये चांगली वाढतात.')
_a('g_Nitrogen', 'Nitrogen (N): makes leaves green and plants grow. Shortage turns older leaves yellow.', 'नाइट्रोजन (N): पत्तियों को हरा रखता है और पौधे को बढ़ाता है। कमी से पुरानी पत्तियां पीली पड़ती हैं।', 'ಸಾರಜನಕ (N): ಎಲೆಗಳನ್ನು ಹಸಿರಾಗಿಸಿ ಗಿಡ ಬೆಳೆಸುತ್ತದೆ. ಕೊರತೆಯಾದರೆ ಹಳೆಯ ಎಲೆಗಳು ಹಳದಿಯಾಗುತ್ತವೆ.', 'நைட்ரஜன் (N): இலைகளைப் பசுமையாக்கி செடியை வளர்க்கிறது. குறைந்தால் பழைய இலைகள் மஞ்சளாகும்.', 'నత్రజని (N): ఆకులను పచ్చగా ఉంచి మొక్కను పెంచుతుంది. లోపిస్తే పాత ఆకులు పసుపు రంగులోకి మారతాయి.', 'नायट्रोजन (N): पाने हिरवी ठेवतो आणि झाडाची वाढ करतो. कमतरतेने जुनी पाने पिवळी पडतात.')
_a('g_Phosphorus', 'Phosphorus (P): helps roots and early growth. Shortage gives small plants with dark or purple leaves.', 'फॉस्फोरस (P): जड़ों और शुरुआती बढ़वार में मदद करता है। कमी से पौधे छोटे और पत्तियां गहरी या बैंगनी रहती हैं।', 'ರಂಜಕ (P): ಬೇರು ಮತ್ತು ಆರಂಭಿಕ ಬೆಳವಣಿಗೆಗೆ ಸಹಾಯ ಮಾಡುತ್ತದೆ. ಕೊರತೆಯಾದರೆ ಗಿಡ ಚಿಕ್ಕದಾಗಿ ಎಲೆಗಳು ಕಡು ಅಥವಾ ನೇರಳೆ ಬಣ್ಣಕ್ಕೆ ತಿರುಗುತ್ತವೆ.', 'பாஸ்பரஸ் (P): வேர் மற்றும் ஆரம்ப வளர்ச்சிக்கு உதவுகிறது. குறைந்தால் செடி சிறியதாகி இலைகள் கருமையாக அல்லது ஊதாவாக மாறும்.', 'భాస్వరం (P): వేర్లు, ప్రారంభ ఎదుగుదలకు సహాయపడుతుంది. లోపిస్తే మొక్క చిన్నగా ఉండి ఆకులు ముదురు లేదా ఊదా రంగులోకి మారతాయి.', 'फॉस्फरस (P): मुळे आणि सुरुवातीच्या वाढीस मदत करतो. कमतरतेने झाडे लहान राहतात आणि पाने गडद किंवा जांभळट होतात.')
_a('g_Potassium', 'Potassium (K): makes plants strong against drought and disease and improves grain and fruit quality.', 'पोटैशियम (K): पौधों को सूखे और रोग से लड़ने की ताकत देता है और दाने व फल की गुणवत्ता सुधारता है।', 'ಪೊಟ್ಯಾಶಿಯಂ (K): ಬರ ಮತ್ತು ರೋಗವನ್ನು ತಡೆಯುವ ಶಕ್ತಿ ಕೊಡುತ್ತದೆ ಮತ್ತು ಕಾಳು, ಹಣ್ಣಿನ ಗುಣಮಟ್ಟ ಹೆಚ್ಚಿಸುತ್ತದೆ.', 'பொட்டாசியம் (K): வறட்சி மற்றும் நோயை எதிர்க்கும் வலிமை தருகிறது, தானியம் மற்றும் பழத்தின் தரத்தை உயர்த்துகிறது.', 'పొటాషియం (K): కరువు, తెగుళ్లను తట్టుకునే శక్తినిస్తుంది, గింజ, పండు నాణ్యత పెంచుతుంది.', 'पोटॅशियम (K): दुष्काळ आणि रोगाशी लढण्याची ताकद देतो आणि दाणे व फळांची गुणवत्ता वाढवतो.')
_a('g_Organic carbon', 'Organic carbon: the living part of soil. Higher is better. FYM and compost raise it.', 'जैविक कार्बन: मिट्टी का जीवित हिस्सा। जितना ज्यादा उतना अच्छा। गोबर की खाद और कंपोस्ट इसे बढ़ाते हैं।', 'ಸಾವಯವ ಇಂಗಾಲ: ಮಣ್ಣಿನ ಜೀವಂತ ಭಾಗ. ಹೆಚ್ಚಿದ್ದಷ್ಟು ಒಳ್ಳೆಯದು. ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ ಮತ್ತು ಕಾಂಪೋಸ್ಟ್ ಇದನ್ನು ಹೆಚ್ಚಿಸುತ್ತವೆ.', 'கரிம கார்பன்: மண்ணின் உயிருள்ள பகுதி. அதிகமாக இருப்பது நல்லது. தொழு உரமும் கம்போஸ்டும் இதை உயர்த்தும்.', 'సేంద్రీయ కర్బనం: నేలలోని సజీవ భాగం. ఎంత ఎక్కువైతే అంత మంచిది. పశువుల ఎరువు, కంపోస్ట్ దీన్ని పెంచుతాయి.', 'सेंद्रिय कर्ब: मातीचा जिवंत भाग. जितका जास्त तितके चांगले. शेणखत आणि कंपोस्ट तो वाढवतात.')
_a('g_Micronutrients', 'Micronutrients (zinc, iron, copper, manganese, boron): needed in tiny amounts, but crops suffer without them.', 'सूक्ष्म पोषक तत्व (जिंक, आयरन, कॉपर, मैंगनीज, बोरॉन): बहुत थोड़ी मात्रा में चाहिए, पर इनके बिना फसल को नुकसान होता है।', 'ಸೂಕ್ಷ್ಮ ಪೋಷಕಾಂಶಗಳು (ಸತು, ಕಬ್ಬಿಣ, ತಾಮ್ರ, ಮ್ಯಾಂಗನೀಸ್, ಬೋರಾನ್): ಬಹಳ ಕಡಿಮೆ ಪ್ರಮಾಣದಲ್ಲಿ ಬೇಕು, ಆದರೆ ಇಲ್ಲದಿದ್ದರೆ ಬೆಳೆಗೆ ತೊಂದರೆ.', 'நுண்ணூட்டச்சத்துகள் (துத்தநாகம், இரும்பு, தாமிரம், மாங்கனீசு, போரான்): மிகக் குறைவாகத் தேவை, ஆனால் இல்லாவிட்டால் பயிர் பாதிக்கும்.', 'సూక్ష్మ పోషకాలు (జింక్, ఇనుము, రాగి, మాంగనీస్, బోరాన్): చాలా తక్కువ మొత్తంలో కావాలి, కానీ లేకపోతే పంట దెబ్బతింటుంది.', 'सूक्ष्म अन्नद्रव्ये (झिंक, लोह, तांबे, मॅंगनीज, बोरॉन): खूप कमी प्रमाणात लागतात, पण त्यांच्याशिवाय पिकाचे नुकसान होते.')
_a('g_Basal dose', 'Basal dose: fertiliser put in at sowing, before the crop starts to grow.', 'बेसल खुराक: बुवाई के समय, फसल उगने से पहले डाली जाने वाली खाद।', 'ಬುಡದ ಗೊಬ್ಬರ: ಬೆಳೆ ಬೆಳೆಯುವ ಮೊದಲು, ಬಿತ್ತನೆ ಸಮಯದಲ್ಲಿ ಹಾಕುವ ಗೊಬ್ಬರ.', 'அடியுரம்: பயிர் வளரத் தொடங்கும் முன், விதைக்கும்போது இடும் உரம்.', 'ఆధార ఎరువు: పంట పెరగడం మొదలయ్యే ముందు, విత్తేటప్పుడు వేసే ఎరువు.', 'बेसल खत: पीक वाढण्यापूर्वी, पेरणीच्या वेळी दिलेले खत.')
_a('g_Top dressing', 'Top dressing: fertiliser given in parts while the crop is growing, mostly urea.', 'टॉप ड्रेसिंग: फसल बढ़ते समय हिस्सों में दी जाने वाली खाद, ज्यादातर यूरिया।', 'ಮೇಲುಗೊಬ್ಬರ: ಬೆಳೆ ಬೆಳೆಯುತ್ತಿರುವಾಗ ಭಾಗಗಳಲ್ಲಿ ಕೊಡುವ ಗೊಬ್ಬರ, ಹೆಚ್ಚಾಗಿ ಯೂರಿಯಾ.', 'மேலுரம்: பயிர் வளரும்போது பகுதிகளாக இடும் உரம், பெரும்பாலும் யூரியா.', 'పై ఎరువు: పంట పెరుగుతున్నప్పుడు భాగాలుగా వేసే ఎరువు, ఎక్కువగా యూరియా.', 'वरखत: पीक वाढत असताना हप्त्याहप्त्याने दिलेले खत, बहुधा युरिया.')
_a('g_FYM', 'FYM: farmyard manure made from cattle dung and bedding. It feeds the soil and improves its structure.', 'एफवाईएम: गोबर और बिछावन से बनी गोबर की खाद। यह मिट्टी को पोषण देती है और उसकी बनावट सुधारती है।', 'ಎಫ್‌ವೈಎಂ: ದನದ ಸೆಗಣಿ ಮತ್ತು ಹಾಸಿಗೆಯಿಂದ ಮಾಡಿದ ಕೊಟ್ಟಿಗೆ ಗೊಬ್ಬರ. ಇದು ಮಣ್ಣಿಗೆ ಪೋಷಣೆ ಕೊಟ್ಟು ರಚನೆ ಸುಧಾರಿಸುತ್ತದೆ.', 'எஃப்ஒய்எம்: மாட்டுச் சாணம் மற்றும் படுக்கையால் ஆன தொழு உரம். இது மண்ணுக்கு ஊட்டம் தந்து அதன் அமைப்பை மேம்படுத்துகிறது.', 'ఎఫ్‌వైఎం: పశువుల పేడ, పరుపుతో చేసిన ఎరువు. ఇది నేలకు పోషణ ఇచ్చి నిర్మాణాన్ని మెరుగుపరుస్తుంది.', 'एफवायएम: गुरांचे शेण आणि गोठ्यातील कचऱ्यापासून बनलेले शेणखत. ते मातीला पोषण देते आणि तिची रचना सुधारते.')
_a('g_Hectare and acre', 'Hectare and acre: 1 hectare is about 2.47 acres. Soil cards often give kg per hectare. This app shows kg per acre too.', 'हेक्टेयर और एकड़: 1 हेक्टेयर लगभग 2.47 एकड़ होता है। मृदा कार्ड में अक्सर किलो प्रति हेक्टेयर लिखा होता है। यह ऐप किलो प्रति एकड़ भी दिखाता है।', 'ಹೆಕ್ಟೇರ್ ಮತ್ತು ಎಕರೆ: 1 ಹೆಕ್ಟೇರ್ ಸುಮಾರು 2.47 ಎಕರೆ. ಮಣ್ಣು ಕಾರ್ಡ್‌ನಲ್ಲಿ ಹೆಚ್ಚಾಗಿ ಕೆಜಿ ಪ್ರತಿ ಹೆಕ್ಟೇರ್ ಇರುತ್ತದೆ. ಈ ಆಪ್ ಕೆಜಿ ಪ್ರತಿ ಎಕರೆಯನ್ನೂ ತೋರಿಸುತ್ತದೆ.', 'ஹெக்டேர் மற்றும் ஏக்கர்: 1 ஹெக்டேர் சுமார் 2.47 ஏக்கர். மண் அட்டையில் பெரும்பாலும் கிலோ/ஹெக்டேர் இருக்கும். இந்த செயலி கிலோ/ஏக்கரையும் காட்டுகிறது.', 'హెక్టారు మరియు ఎకరా: 1 హెక్టారు సుమారు 2.47 ఎకరాలు. సాయిల్ కార్డ్‌లో తరచుగా కిలోలు/హెక్టారు ఉంటుంది. ఈ యాప్ కిలోలు/ఎకరా కూడా చూపుతుంది.', 'हेक्टर आणि एकर: 1 हेक्टर म्हणजे सुमारे 2.47 एकर. मृदा पत्रिकेत बहुधा किलो प्रति हेक्टर असते. हे अॅप किलो प्रति एकरही दाखवते.')
_a('g_Soil Health Card', 'Soil Health Card: a government card with your soil test results and advice. Get it free from your agriculture office.', 'मृदा स्वास्थ्य कार्ड: सरकार का कार्ड जिसमें आपकी मिट्टी की जांच और सलाह होती है। यह कृषि कार्यालय से मुफ्त मिलता है।', 'ಮಣ್ಣು ಆರೋಗ್ಯ ಕಾರ್ಡ್: ನಿಮ್ಮ ಮಣ್ಣು ಪರೀಕ್ಷೆ ಫಲಿತಾಂಶ ಮತ್ತು ಸಲಹೆ ಇರುವ ಸರ್ಕಾರಿ ಕಾರ್ಡ್. ಕೃಷಿ ಕಚೇರಿಯಲ್ಲಿ ಉಚಿತವಾಗಿ ಸಿಗುತ್ತದೆ.', 'மண் ஆரோக்கிய அட்டை: உங்கள் மண் பரிசோதனை முடிவுகளும் ஆலோசனையும் உள்ள அரசு அட்டை. வேளாண் அலுவலகத்தில் இலவசமாகக் கிடைக்கும்.', 'సాయిల్ హెల్త్ కార్డ్: మీ నేల పరీక్ష ఫలితాలు, సలహా ఉన్న ప్రభుత్వ కార్డ్. వ్యవసాయ కార్యాలయంలో ఉచితంగా లభిస్తుంది.', 'मृदा आरोग्य पत्रिका: तुमच्या माती तपासणीचे निकाल आणि सल्ला असलेले सरकारी कार्ड. कृषी कार्यालयात मोफत मिळते.')
_a('g_ppm', 'ppm: parts per million. A way to write very small amounts, used for micronutrients.', 'पीपीएम: पार्ट्स पर मिलियन। बहुत छोटी मात्रा लिखने का तरीका, सूक्ष्म पोषक तत्वों के लिए।', 'ಪಿಪಿಎಂ: ಪಾರ್ಟ್ಸ್ ಪರ್ ಮಿಲಿಯನ್. ಬಹಳ ಸಣ್ಣ ಪ್ರಮಾಣ ಬರೆಯುವ ವಿಧಾನ, ಸೂಕ್ಷ್ಮ ಪೋಷಕಾಂಶಗಳಿಗೆ ಬಳಸುತ್ತಾರೆ.', 'பிபிஎம்: பார்ட்ஸ் பெர் மில்லியன். மிகச் சிறிய அளவை எழுதும் முறை, நுண்ணூட்டச்சத்துகளுக்குப் பயன்படுகிறது.', 'పీపీఎం: పార్ట్స్ పర్ మిలియన్. చాలా చిన్న మొత్తాన్ని రాసే పద్ధతి, సూక్ష్మ పోషకాలకు వాడతారు.', 'पीपीएम: पार्ट्स पर मिलियन. खूप लहान प्रमाण लिहिण्याची पद्धत, सूक्ष्म अन्नद्रव्यांसाठी वापरतात.')


def lang_index(lang: str) -> int:
    return LANGS.index(lang) if lang in LANGS else 0


def t(code: str, lang: str = 'English', **kw) -> str:
    row = _T.get(code)
    text = row[lang_index(lang)] if row else code
    if kw:
        try:
            text = text.format(**kw)
        except (KeyError, IndexError):
            pass
    return text


def has(code: str) -> bool:
    return code in _T


def en(code: str, **kw) -> str:
    return t(code, 'English', **kw)


def num(x, lang='English') -> str:
    """Digits stay Western so they match the soil card and the shop bill."""
    return str(x)


